<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$facility=$id?fetch_one('SELECT sf.*,sp.business_name,u.full_name AS contact_name,u.id AS provider_user_id,l.province,l.district,l.tehsil,l.area,GROUP_CONCAT(DISTINCT pc.name ORDER BY pc.name SEPARATOR ", ") AS supported_products FROM storage_facilities sf JOIN storage_providers sp ON sp.id=sf.provider_id JOIN users u ON u.id=sp.user_id JOIN locations l ON l.id=sf.location_id LEFT JOIN facility_supported_products fsp ON fsp.facility_id=sf.id LEFT JOIN produce_categories pc ON pc.id=fsp.category_id WHERE sf.id=:id AND sf.status="active" GROUP BY sf.id',['id'=>$id]):null;if($facility===null){http_response_code(404);require __DIR__.'/../404.php';exit;}$images=fetch_all('SELECT file_path,alt_text FROM storage_facility_images WHERE facility_id=:id ORDER BY is_primary DESC,sort_order,id',['id'=>$id]);$rating=fetch_one('SELECT AVG(rating) AS average_rating,COUNT(*) AS review_count FROM reviews WHERE reviewed_user_id=:user AND status="published"',['user'=>$facility['provider_user_id']]);$pageTitle=$facility['name'];require __DIR__.'/../includes/header.php';
?>
<section class="section"><div class="site-container listing-detail-layout"><div><?php if($images===[]):?><div class="listing-visual-placeholder" aria-label="No facility image uploaded"></div><?php else:?><img class="listing-detail-image" src="<?= e(app_url($images[0]['file_path'])) ?>" alt="<?= e($images[0]['alt_text']??$facility['name']) ?>"><?php endif;?></div><article class="listing-detail-panel"><span class="badge"><?= e(order_status_label($facility['storage_type'])) ?></span><h1><?= e($facility['name']) ?></h1><p><?= e(implode(', ',array_filter([$facility['area'],$facility['tehsil'],$facility['district'],$facility['province']]))) ?></p><div class="detail-facts"><div><span>Available capacity</span><strong><?= number_format((float)$facility['available_capacity_kg'],0) ?> kg</strong></div><div><span>Total capacity</span><strong><?= number_format((float)$facility['total_capacity_kg'],0) ?> kg</strong></div><div><span>Daily price</span><strong>Rs. <?= number_format((float)$facility['price_per_kg_day'],2) ?>/kg</strong></div><div><span>Verified-order rating</span><strong><?= (int)$rating['review_count']>0?number_format((float)$rating['average_rating'],1).' / 5 ('.(int)$rating['review_count'].')':'No verified reviews yet' ?></strong></div></div><h2>Supported produce</h2><p><?= e($facility['supported_products']?:'Contact the provider through a booking request to confirm compatibility.') ?></p><h2>Facility notes</h2><p><?= e($facility['description']?:'No additional facility notes have been published.') ?></p><a class="button button-primary" href="<?= e(app_url('storage/index.php?facility='.(int)$facility['id'].'#book-storage')) ?>">Request booking</a></article></div></section>
<?php require __DIR__.'/../includes/footer.php'; ?>
